mapper.select:
SELECT ut.id, ut.user_id, ut.tag_id, ut.use_count, -- 选取热度字段 ut.create_time, t.tag_name -- 选取标签名称用于展示和搜索 FROM user_tags ut LEFT JOIN tags_dictionary t ON ut.tag_id = t.tag_id WHERE ut.user_id = #{userId}
AND t.tag_name LIKE CONCAT('%', #{tagName}, '%')
ORDER BY ut.use_count DESC, ut.id DESC
